#include "dsp/cz_presets.h"

/*
 * The EasyCZ presets: original tones, each in a category that the Move shows
 * as a folder (Keys, Bass, Brass & Leads, Strings & Pads, Bells & Plucks,
 * Organs, Drums & FX). Presets of one category must be listed together.
 *
 * Envelopes are written {{rates}, {levels}, sustain step, end step}, in
 * front-panel units: rates and levels 0-99, steps 1-8, sustain 0 = none.
 * Panel guide (from the chip's laws): a full DCA fall takes ~3.4 ms at rate
 * 99, 25 ms at 80, 200 ms at 60, 540 ms at 50, 1.6 s at 40, 13 s at 20. DCA
 * levels are 0.5 dB per step: 90 is -4.5 dB, 80 is -9.5, 60 is -19.5. A DCO
 * level of 0-63 is 1/8 semitone per step; 64-99 is 2 semitones per step
 * above 60 (level 72 = +24 semitones).
 *
 * Each entry is {name, category, chorus, level, panel tone}: chorus 1 turns
 * on the stereo chorus when the preset is chosen (it can still be switched);
 * level is the preset's volume in dB, set so the bank plays at an even
 * loudness (tests/level_presets.c measures it).
 *
 * A tone that leaves line 2 empty (wave1 0) plays line 1's settings on line 2.
 * Detune applies to the second line (1' or 2') only.
 */

/* Categories, shown as folders. Presets of one category are listed together. */
#define CAT_KEYS "Keys"
#define CAT_BASS "Bass"
#define CAT_BRASS_LEADS "Brass & Leads"
#define CAT_STRINGS_PADS "Strings & Pads"
#define CAT_BELLS_PLUCKS "Bells & Plucks"
#define CAT_ORGANS "Organs"
#define CAT_DRUMS_FX "Drums & FX"

#define FLAT {{99}, {0}, 0, 1} /* DCO: no pitch movement */
#define NO_DETUNE .detune_sign = 1
#define DETUNE(oct, note, fine) .detune_sign = 1, .detune_oct = oct, .detune_note = note, .detune_fine = fine
#define VIBRATO(delay, rate, depth) .vib_wave = CZ_VIB_TRI, .vib_delay = delay, .vib_rate = rate, .vib_depth = depth

